/**
 * generated by stackra gen from src/config/seo.config.ts (robots) and src/config/site.config.ts
 * (previewHostPrefixes) — do not edit
 * Purpose: `/robots.txt` per site: one group per configured crawler with its allows and disallows,
 *          and the sitemap index link, on a live site; disallow everything on a preview host or a
 *          sandbox tenant.
 * Boundary: the groups are the config's, read from the container per request; a resource route
 *           with no UI and no cookie.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { robotsTxt } from "@stackra/seo/robots";
import type { Route } from "./+types/robots";
import { SeoConfig } from "#src/config/seo.config";
import { resolveSite } from "#src/providers/site/resolve-site";

export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args);
  const site = await resolveSite(ctx);
  const groups = Object.entries(ctx.config(SeoConfig).robots).map(([userAgent, group]) => ({
    userAgent,
    allow: group.allow,
    disallow: group.disallow,
  }));
  const body = site.indexable
    ? robotsTxt({ groups, sitemap: `${site.origin}/sitemap.xml` })
    : robotsTxt({ groups: [{ userAgent: "*", allow: [], disallow: ["/"] }] });
  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
